source='''from collections import deque


def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    fill_by_side = {5: 8, 7: 4, 9: 3}
    seen = set()
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 2 or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            component = set()
            while q:
                y, x = q.popleft()
                component.add((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < h and 0 <= nx < w and grid[ny][nx] == 2 and (ny, nx) not in seen:
                        seen.add((ny, nx))
                        q.append((ny, nx))
            r0 = min(y for y, x in component)
            r1 = max(y for y, x in component)
            c0 = min(x for y, x in component)
            c1 = max(x for y, x in component)
            if r1 - r0 != c1 - c0 or r1 - r0 not in (4, 6, 8):
                continue
            border = ({(r0, x) for x in range(c0, c1 + 1)} |
                      {(r1, x) for x in range(c0, c1 + 1)} |
                      {(y, c0) for y in range(r0, r1 + 1)} |
                      {(y, c1) for y in range(r0, r1 + 1)})
            if component == border:
                color = fill_by_side[r1 - r0 + 1]
                for y in range(r0 + 1, r1):
                    for x in range(c0 + 1, c1):
                        if out[y][x] == 0:
                            out[y][x] = color
    return out
'''
